#include <bits/stdc++.h>
using namespace std;

void solve(){
    int n,k; cin>>n>>k;
    string s; cin>>s;
    int i=0;
    while(s[i]!='G' and i<n){
       i++;
    }
 
    int bg1=0,bg2=0;
    
    while(bg1<k+1 and i<n){
        if(s[i]=='G'){
            bg1++;
        }
        i++;
    }
    
    if(i==n and bg1<=k+1){cout<<"YES"<<"\n"; return;}
    
    
    while(s[i]!='G' and i<n){
       i++;
    }
    
        
    while(bg2<k+1 and i<n){
        if(s[i]=='G') bg2++;
        else{bg2+=2;}
        i++;
    }
    
   // cout<<i<<"\n";
    if(i==n and bg2<=k+1){cout<<"YES"<<"\n";}
    else{cout<<"NO"<<"\n";}
    

}

int main() {
	int t;cin>>t;
	while(t--){
	    solve();
	}

}
